// Usage: dotnet run -c Release -- <games> <rngSeed> <outFile> [maxPlies]
// Output: one JSON object per line: { seed, queenDrops, plies: [{ gold, legal, move }], result }
// (queenDrops: true = current rules with placements next to queens; older data lacks it)
// Squares are ids (y * size + x). Moves: "m<from>-<to>" or "p<kind><to>" (kind = q r b n p).
//
// Seeds mode: dotnet run -c Release -- seeds <count> <size> <m|r> <outFile>
// Writes one map seed per line, generated by the server's MapGenerator.

using System.Text.Json;
using AgeOfChess.Server.GameLogic;
using AgeOfChess.Server.GameLogic.Map;
using AgeOfChess.Server.GameLogic.PlaceableObjects;
using AgeOfChess.Server.GameLogic.PlaceableObjects.Pieces;

if (args.Length > 0 && args[0] == "seeds")
{
    int count = int.Parse(args[1]), boardSize = int.Parse(args[2]);
    bool random = args[3] == "r";
    using var w = new StreamWriter(args[4]);
    for (int i = 0; i < count; i++)
    {
        var gen = new MapGenerator();
        w.WriteLine((random ? gen.GenerateFullRandom(boardSize, boardSize) : gen.GenerateMirrored(boardSize, boardSize)).Seed);
    }
    return;
}

int games = args.Length > 0 ? int.Parse(args[0]) : 50;
var rng = new Random(args.Length > 1 ? int.Parse(args[1]) : 1);
string outFile = args.Length > 2 ? args[2] : "oracle.jsonl";
int maxPlies = args.Length > 3 ? int.Parse(args[3]) : 300;

int[] sizes = [10, 10, 10, 8, 12, 6, 14, 16];
var pieceTypes = new (Type type, string code)[]
{
    (typeof(Queen), "q"), (typeof(Rook), "r"), (typeof(Bishop), "b"), (typeof(Knight), "n"), (typeof(Pawn), "p"),
};

using var writer = new StreamWriter(outFile);
for (int g = 0; g < games; g++)
{
    int size = sizes[g % sizes.Length];
    var gen = new MapGenerator();
    var map = g % 3 == 2 ? gen.GenerateFullRandom(size, size) : gen.GenerateMirrored(size, size);
    // Round-trip through the seed so the Rust side sees exactly the same board.
    string seed = map.Seed;
    map = new MapGenerator().GenerateFromSeed(seed);
    var game = new OracleGame(map);

    var plies = new List<object>();
    // Bias per game so some games are placement-heavy (many pieces), others move-heavy.
    double placeBias = rng.NextDouble();

    for (int ply = 0; ply < maxPlies && !game.GameEnded; ply++)
    {
        var legal = LegalMoves(game, pieceTypes);
        var gold = new[] { game.White.Gold, game.Black.Gold };
        if (legal.Count == 0)
        {
            // Game.StartNewTurn should already have ended the game; record and stop.
            plies.Add(new { gold, legal = legal.Select(m => m.code).OrderBy(s => s, StringComparer.Ordinal).ToList(), move = (string?)null });
            break;
        }

        var placements = legal.Where(m => m.code[0] == 'p').ToList();
        var pool = placements.Count > 0 && rng.NextDouble() < placeBias * 0.6 ? placements : legal;
        // Buy queens often so many positions have queens to place next to.
        var queenBuys = legal.Where(m => m.code.StartsWith("pq")).ToList();
        if (queenBuys.Count > 0 && rng.NextDouble() < 0.3) pool = queenBuys;
        var chosen = pool[rng.Next(pool.Count)];
        plies.Add(new { gold, legal = legal.Select(m => m.code).OrderBy(s => s, StringComparer.Ordinal).ToList(), move = chosen.code });

        if (!chosen.apply()) throw new Exception($"Oracle move rejected: {chosen.code} in {seed}");
        game.EndTurn();
        game.StartNewTurn();
    }

    writer.WriteLine(JsonSerializer.Serialize(new { seed, queenDrops = true, plies, result = game.Result }));
    Console.WriteLine($"game {g + 1}/{games}: {seed[..8]}… plies={plies.Count} result={game.Result ?? "-"}");
}

static List<(string code, Func<bool> apply)> LegalMoves(OracleGame game, (Type type, string code)[] pieceTypes)
{
    var map = game.GetMap();
    int size = map.Width;
    var result = new List<(string, Func<bool>)>();
    var active = game.ActiveColor;

    foreach (var sq in map.Squares.Where(s => s.Object is Piece p && p.IsWhite == active.IsWhite).ToList())
    {
        var piece = (Piece)sq.Object!;
        foreach (var dest in map.FindLegalDestinationsForPiece(piece, sq).Distinct().ToList())
        {
            // Same simulation filter as Game.TryMovePiece
            var captured = dest.Object;
            sq.ClearObject();
            dest.SetObject(piece);
            var kingSq = map.Squares.Single(s => s.Object is King k && k.IsWhite == active.IsWhite);
            bool inCheck = new PathFinder(map).FindCheckingSourceSquares(kingSq).Any();
            dest.SetObject(captured);
            sq.SetObject(piece);
            if (inCheck) continue;

            int fromId = sq.Id, toId = dest.Id;
            int fx = sq.X, fy = sq.Y, tx = dest.X, ty = dest.Y;
            result.Add(($"m{fromId}-{toId}", () => game.TryMovePiece(fx, fy, tx, ty)));
        }
    }

    foreach (var (type, code) in pieceTypes)
    {
        if (active.Gold < Game.GetPieceCost(type)) continue;
        var dests = game.FindLegalPlacements(type).Distinct().ToList();
        foreach (var dest in dests)
        {
            int tx = dest.X, ty = dest.Y;
            result.Add(($"p{code}{dest.Id}", () => game.TryPlacePiece(tx, ty, type)));
        }
    }

    return result;
}

class OracleGame : Game
{
    public OracleGame(Map map)
    {
        Map = map;
        Colors = [new PieceColor(true, "white"), new PieceColor(false, "black")];
        TimeControlEnabled = false;
    }
}

namespace AgeOfChess.Server.Services
{
    // MapGenerator.cs has `using AgeOfChess.Server.Services;` but doesn't use anything from it.
    internal static class Placeholder { }
}
